314:  /**
315:   * Open a claim's editor: the claim is locked for other users and the form takes its values. Only a
316:   * DRAFT claim can be edited; any other is refused with an error on its row (to change an OPEN claim,
317:   * void it and add a new one), as is one due by in a closed period, both taking no lock. A claim
318:   * another user's editor holds is refused with an error on its row, the form left on it to save once
319:   * the lock is released; a viewer's edit is refused like any of their actions.
320:   */
321:  protected async open(claim: ClaimView): Promise<void> {
322:    this.claimError.set(null);
323:    const sheet = this.session.sheet();
324:    if (!sheet) return;
325:    if (claim.status !== 'DRAFT') {
326:      this.reset();
327:      this.claimError.set({
328:        id: claim.id,
329:        message: `A ${claim.status} claim cannot be edited; void it and add a new one.`,
330:      });
331:      return;
332:    }
333:    const period = periodOn(this.periods(), claim.dueBy);
334:    if (period?.closed) {
335:      this.reset();
336:      this.claimError.set({ id: claim.id, message: `Period ${period.name} is closed, so its claims cannot be edited.` });
337:      return;
338:    }
339:    const me = this.session.user()?.trim();
340:    if (claim.lockedBy !== null && claim.lockedBy !== me) {
341:      this.setEditing(claim.id);
342:      this.claimError.set({ id: claim.id, message: this.lockedMessage(claim.lockedBy) });
343:      return;
344:    }
345:    const previous = this.editing();
346:    // the form is the claim's from the press on, so a save typed before the lock answers edits it
347:    this.setEditing(claim.id);
348:    this.typedSinceOpen = false;
349:    // the form shows the claim as listed at once, so a field typed before the lock answers keeps the rest
350:    this.fill(claim);
