352:      const locked = await this.api.lock(sheet, claim.id);
353:      this.saved.emit(locked);
354:      if (previous !== null && previous !== claim.id) void this.release(sheet, previous);
355:      if (this.editing() === claim.id && !this.typedSinceOpen) this.fill(locked);
