358:      if (status !== 423 && this.editing() === claim.id) this.setEditing(previous);
359:      this.claimError.set({
360:        id: claim.id,
361:        message: status === 423
362:          ? this.lockedMessage(null)
363:          : status === 403
364:            ? 'Your role is not allowed to edit a claim.'
365:            : 'The claim cannot be edited.',
366:      });
367:    }
368:  }
