374:  protected async cancel(claim: ClaimView): Promise<void> {
375:    this.claimError.set(null);
376:    if (this.editing() === claim.id) this.reset();
377:    const sheet = this.session.sheet();
378:    if (sheet) await this.release(sheet, claim.id);
379:  }
