381:  /** The form's own cancel: the editor open in it is cancelled. */
382:  protected cancelEditor(): void {
383:    const id = this.editing();
384:    const claim = this.claims().find((c) => c.id === id);
385:    if (claim) void this.cancel(claim);
386:    else this.reset();
387:  }
388:
389:  /** Release this user's lock on a claim; one that cannot be released is left to the sheet's next today. */
390:  private async release(sheet: string, id: number): Promise<void> {
391:    try {
392:      this.saved.emit(await this.api.unlock(sheet, id));
393:    } catch {
394:      // nothing of this user's to release
395:    }
396:  }
