275:    const floor = cents(valueOn(this.session.floorHistory(), claim.date, '1.00'));
276:    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today);
277:    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), floor, late, halfUp);
278:    return figure === null ? NO_RATE : money(figure);
